const applyToTargets = async (targets, items, tempHP) => {
  const itemObjects = await Promise.all(items.map(uuid => fromUuid(uuid)));
  for (const target of targets) {
    await target.createEmbeddedDocuments("Item", itemObjects.map(i => i.toObject()));
    if (tempHP > 0) {
      const currentTempHP = target.system.tempHp.value || 0;
      await target.update({ "system.tempHp.value": currentTempHP + tempHP });
    }
  }
};

// get the context if it exists
if (scope.context && scope.context.message?.flags?.ptu?.macroApply !== undefined) {
  if (!game.user.isGM) {
    ui.notifications.error("This button is supposed to be triggered by the GM");
    return;
  }
  const message = scope.context.message;
  const { items, tempHP, targets } = scope.context.message?.flags?.ptu?.macroApply || {};
  const targetObjects = await Promise.all(targets.map(uuid => fromUuid(uuid)));
  return applyToTargets(targetObjects, items, tempHP).then(()=>{
    return message.delete();
  }).catch(console.error);
}


// If this has been invoked without a chat message or without the chat message flags, grab the targets and open a dialog

// get all targets
const allTargets = [...game.user.targets.map(t=>t.actor)];
const targets = allTargets.filter(t=>t.isOwner);
const unapplyableTargets = allTargets.filter(t=>!t.isOwner);

(new Promise(async (resolve, reject) => {
  class ItemDialog extends foundry.applications.api.DialogV2 {
      _onRender(context, options) {
        super._onRender(context, options);
        const html = $(this.element);

        //
        // set up drag and drop area
        //
        const dropZone = html.find('#item-drop-zone')[0];
        const itemsList = html.find('#dropped-items-list');
        const items = [];

        // Set up drag and drop handlers
        dropZone.addEventListener('dragover', (e) => {
          e.preventDefault();
          dropZone.style.backgroundColor = '#f0f0f0';
        });

        dropZone.addEventListener('dragleave', (e) => {
          e.preventDefault();
          dropZone.style.backgroundColor = 'transparent';
        });

        dropZone.addEventListener('drop', async (e) => {
          e.preventDefault();
          dropZone.style.backgroundColor = 'transparent';

          const data = TextEditor.getDragEventData(e);
          const item = await (async ()=>{
            let item = await fromUuid(data.uuid);
            if (!item) return null;
            if (item instanceof RollTable) {
              let result = await item.roll();
              if (result.results.length != 1) {
                return null;
              } else {
                let r = result.results[0];
                let uuid = "";
                if (r.type == "pack") {
                  uuid = `Compendium.${r.documentCollection}.Item.${r.documentId}`;
                } else {
                  return null;
                }
                item = await fromUuid(uuid);
              }
            }
            return item;
          })()
          if (!item) return;

          items.push(item.uuid);
          itemsList.data('items', items);

          // Update visual list
          const itemElement = document.createElement('div');
          itemElement.innerHTML = `
            <div class="item" style="display: flex; align-items: center; margin: 5px 0;">
              <img src="${item.img}" width="24" height="24" style="margin-right: 8px;">
              <span>${item.name}</span>
              <a class="remove-item" style="margin-left: auto;"><i class="fas fa-times"></i></a>
            </div>
          `;

          // Add remove handler
          itemElement.querySelector('.remove-item').addEventListener('click', () => {
            const index = items.indexOf(item);
            if (index > -1) {
              items.splice(index, 1);
              itemsList.data('items', items);
              itemElement.remove();
            }
          });

          itemsList.append(itemElement);
        });
      }
    }

  ItemDialog.wait({
    window: { title: 'Effect to Add' },
    content: `
          <fieldset>
            <legend>Targets</legend>
            <ul>
              ${targets.map(t => `<li>${t.name}</li>`).join('')}
            </ul>
          </fieldset>
          <div class="form-group">
            <label>Temp HP Addition</label>
            <input type="number" name="tempHP" value="0" style="width: 100%;">
          </div>
          <div class="form-group">
            <div id="item-drop-zone" style="min-height: 100px; border: 2px dashed #ccc; padding: 10px; margin-bottom: 10px;">
              <p class="drop-text">Drag and drop effects here</p>
              <div id="dropped-items-list"></div>
            </div>
          </div>
      `,
    buttons: [{
      action: "ok",
      label: "OK",
      default: true,
      callback: (event, button, dialog) => {
        const items = $(dialog.element).find('#dropped-items-list').data('items') || [];
        const tempHP = parseInt($(dialog.element).find('input[name="tempHP"]').val()) || 0;
        resolve({ items, tempHP });
      },
    }],
    close: () => reject(null),
  }).catch(() => {
    reject(null);
  });
})).then(async ({ items, tempHP }) => {
  await applyToTargets(targets, items, tempHP);
  if (unapplyableTargets.length == 0) return;
  return ChatMessage.create({
    content: `<p>${game.user.name} attempted to apply effects to actors they do not own. GM Permission is required to continue. To apply, the GM may click the following button:</p><p><strong>@UUID[Compendium.ptu.macros.Macro.g4RwxoMNTTKBN0bJ]{Apply Effects}</strong></p>`,
    flags: {
      ptu: {
        macroApply: {
          items,
          tempHP,
          targets: unapplyableTargets.map(t=>t.uuid),
        }
      }
    }
  });
}).catch(console.error);
